11	const byYear = new Map<number, GardenEntry[]>();
12	for (const entry of entries) {
13		const year = entry.updatedAt.getFullYear();
14		byYear.set(year, [...(byYear.get(year) ?? []), entry]);
15	}
16	const years = [...byYear.keys()].sort((a, b) => b - a);
