function srgbToLinear(c){ c/=255; return c<=0.04045 ? c/12.92 : Math.pow((c+0.055)/1.055,2.4); }
function linearToSrgb(c){ c = c<=0.0031308 ? c*12.92 : 1.055*Math.pow(c,1/2.4)-0.055; return Math.round(Math.min(1,Math.max(0,c))*255); }
function rgbToOklab(r,g,b){
  r=srgbToLinear(r); g=srgbToLinear(g); b=srgbToLinear(b);
  const l=0.4122214708*r+0.5363325363*g+0.0514459929*b;
  const m=0.2119034982*r+0.6806995451*g+0.1073969566*b;
  const s=0.0883024619*r+0.2817188376*g+0.6299787005*b;
  const l_=Math.cbrt(l), m_=Math.cbrt(m), s_=Math.cbrt(s);
  return [
    0.2104542553*l_+0.7936177850*m_-0.0040720468*s_,
    1.9779984951*l_-2.4285922050*m_+0.4505937099*s_,
    0.0259040371*l_+0.7827717662*m_-0.8086757660*s_
  ];
}
function oklabToRgb(L,a,b){
  const l_=L+0.3963377774*a+0.2158037573*b;
  const m_=L-0.1055613458*a-0.0638541728*b;
  const s_=L-0.0894841775*a-1.2914855480*b;
  const l=l_**3, m=m_**3, s=s_**3;
  const r=4.0767416621*l-3.3077115913*m+0.2309699292*s;
  const g=-1.2684380046*l+2.6097574011*m-0.3413193965*s;
  const bl=-0.0041960863*l-0.7034186147*m+1.7076147010*s;
  return [linearToSrgb(r),linearToSrgb(g),linearToSrgb(bl)];
}
function hex(rgb){ return "#"+rgb.map(v=>v.toString(16).padStart(2,"0")).join(""); }
function mix(hex1,hex2,pct){
  const c1=[parseInt(hex1.slice(1,3),16),parseInt(hex1.slice(3,5),16),parseInt(hex1.slice(5,7),16)];
  const c2=[parseInt(hex2.slice(1,3),16),parseInt(hex2.slice(3,5),16),parseInt(hex2.slice(5,7),16)];
  const [L1,a1,b1]=rgbToOklab(...c1);
  const [L2,a2,b2]=rgbToOklab(...c2);
  const L=L1*pct+L2*(1-pct), a=a1*pct+a2*(1-pct), b=b1*pct+b2*(1-pct);
  return hex(oklabToRgb(L,a,b));
}
